import { useEffect, useMemo, useState } from 'react';
import styles from './index.module.less';
import { JSONSchemaCustom, SchemaForm, SchemaQueryForm } from '@/components/schema';
import { Button, Form, Input, Message, Modal, Space, Tag, Image, Empty } from "@arco-design/web-react";
import ajax, { uploadFile } from '@/utils/ajax';
import { AsyncButton, Selector, Uploader } from '@/components/custom';
import { useObserver } from 'mobx-react-lite';
import { IconDelete } from '@arco-design/web-react/icon';
import store from './store';
import { getUuid } from '@/utils';
import { calculateFileHash } from '@/utils/file';


const Index = () => {

    const [visible, setVisible] = useState<boolean>(false);
    const [url, setUrl] = useState<string>("");
    const [name, setName] = useState<string>("")
    const [form] = Form.useForm();

    return useObserver(() => {
        const { tagId, setTagId, tags, setTags } = store;

        useEffect(() => {
            store.getTags();
        },[])

        useEffect(() => {
            store.getList();
        },[tagId])


        return (
            <div className={styles.imgList}>
                <div className={styles.header} style={{ paddingBottom: 10 }}>
                    <Space size="mini">
                        {tags.map((o) => {
                            return (
                                <Tag key={o.id}
                                    checked={o.id === tagId}
                                    checkable
                                    onCheck={() => {
                                        setTagId(o.id)
                                    }}
                                    color='arcoblue'
                                >
                                    {o.name}
                                </Tag>
                            )
                        })}
                    </Space>
                    <Space>
                        <Input
                            addBefore="图片名称"
                            placeholder="请输入"
                            value={name}
                            onChange={setName}
                        />
                        <Input
                            value={url}
                            onChange={setUrl}
                            addAfter={(
                                <AsyncButton type="text"
                                    onClick={() => {
                                        return fetch(url) // 替换成你的图片 URL
                                        .then(response => response.blob())
                                        .then(async (blob) => {
                                            const file = new File([blob], 'image.png', { type: 'image/png' });
                                            const hash = await calculateFileHash(file);
                                            console.log('hash', hash)
                                            const { url } = await uploadFile(
                                                file,
                                                `${hash.slice(0,2)}/${hash.slice(2,4)}/${hash.slice(4,6)}/${hash.slice(6)}.png`
                                            );
                                            await ajax.post('/apijson/post', {
                                                "ImageList": {
                                                    tagId: store.tagId,
                                                    name: name,
                                                    url
                                                }
                                            }).then(() => {
                                                Message.success("上传成功")
                                                setVisible(false);
                                                setUrl("");
                                                setName("");
                                                store.getList();
                                            })
                                        })
                                    }}
                                >
                                    上传
                                </AsyncButton>
                            )}
                            placeholder="请输入链接"
                            addBefore={"URL快传"}
                        />
                        <Button
                            type="primary"
                            onClick={() => {
                                form.clearFields();
                                setVisible(true);
                            }}
                        >
                            上传图片
                        </Button>
                    </Space>
                </div>
                <div className={styles['waterfall-container']}>
                    {store.list.map((o) => {
                        return (
                            <Image
                                className={styles['waterfall-item']}
                                key={o.id}
                                preview
                                previewProps={{ src: o.url }}
                                src={`${o.url}?x-oss-process=image/auto-orient,1/resize,m_lfit,w_300/quality,q_90`}
                                error={(
                                    <Empty 
                                        description={(
                                            <Button
                                                onClick={() => {
                                                    return ajax.post("/apijson/delete", {
                                                        ImageList: {
                                                            id: o.id
                                                        }
                                                    }).then(() => {
                                                        Message.success("删除成功")
                                                        store.getList();
                                                    })
                                                }}
                                            >已损坏</Button>
                                        )} 
                                    />
                                )}
                                actions={[
                                    <Button
                                        type="primary"
                                        status="danger"
                                        icon={<IconDelete />}
                                        onClick={() => {
                                            Modal.confirm({
                                                title: "确认删除",
                                                content: "请确认是否删除当前图片",
                                                onOk: () => {
                                                    return ajax.post("/apijson/delete", {
                                                        ImageList: {
                                                            id: o.id
                                                        }
                                                    }).then(() => {
                                                        Message.success("删除成功")
                                                        store.getList();
                                                    })
                                                }
                                            })
                                        }}
                                    ></Button>
                                ]}
                            />
                        )
                    })}
                    <div style={{ flex: "3 0 100px" }}></div>
                    <div style={{ flex: "3 0 100px" }}></div>
                </div>
                <Modal 
                    visible={visible}
                    style={{ width: 600 }}
                    title="上传图片"
                    onCancel={() => {
                        setVisible(false);
                    }}
                    unmountOnExit
                    onOk={() => {
                        return form.validate().then((res) => {
                            ajax.post('/apijson/post', {
                                "ImageList": {
                                    ...res,
                                }
                            }).then(() => {
                                Message.success("上传成功")
                                setVisible(false);
                                store.getList();
                            })
                        })
                    }}
                >
                    <Form form={form}
                        initialValues={{ tagId: store.tagId }}
                    >
                        <Form.Item label="请选择标签" field="tagId"
                            rules={[{ required: true }]}
                        >
                            <Selector type="imgTags" />
                        </Form.Item>
                        <Form.Item label="图片名称" field="name"
                            rules={[{ required: true }]}
                        >
                            <Input placeholder="请输入" />
                        </Form.Item>
                        <Form.Item label="上传图片" field="url"
                            rules={[{ required: true }]}
                        >
                            <Uploader
                                multiple
                                onChange={(img, data) => {
                                    console.log('data', data)
                                    if(data){
                                        form.setFieldsValue({
                                            name: data.name,
                                            size: data.size,
                                        })
                                    }
                                }}
                            />
                        </Form.Item>
                        <Form.Item field="size" noStyle></Form.Item>
                    </Form>
                </Modal>
            </div>
        )
    })
}

export default Index;